{
  "story": "Cross-validation splits data into folds to train on some and test on others. By checking out-of-sample error across multiple rounds, it exposes models that memorize training noise rather than learning true patterns.",
  "aha": {
    "stateId": "fold3",
    "observation": "When validation error spikes while training error drops, the model is overfitting."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "completedBefore": "state.id"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Cross-Validation Step",
      "options": ["fold1", "fold2", "fold3", "fold4", "fold5"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "5-Fold CV Overfitting Check",
        "regions": [
          {
            "id": "trainSet",
            "label": "Training Folds",
            "values": ["Fold 1", "Fold 2", "Fold 3", "Fold 4"]
          },
          {
            "id": "valSet",
            "label": "Validation Fold",
            "values": ["Fold 5"]
          },
          {
            "id": "metricPanel",
            "label": "Error Tracker",
            "values": ["Train Err: 2%", "Val Err: 24%"]
          }
        ],
        "states": [
          {
            "id": "fold1",
            "label": "Fold 1",
            "short": "Step 1",
            "sentence": "Fold 1 serves as validation while folds 2-5 train the model.",
            "why": "Establishes baseline score on unseen fold 1.",
            "active": ["valSet"],
            "calloutRegion": "valSet",
            "readouts": [
              {"id": "t1", "label": "Train Error", "value": "3%"},
              {"id": "v1", "label": "Val Error", "value": "18%"}
            ]
          },
          {
            "id": "fold2",
            "label": "Fold 2",
            "short": "Step 2",
            "sentence": "Fold 2 is held out for validation in the second round.",
            "why": "Continues rotation across folds.",
            "active": ["valSet"],
            "calloutRegion": "valSet",
            "readouts": [
              {"id": "t2", "label": "Train Error", "value": "2.5%"},
              {"id": "v2", "label": "Val Error", "value": "19%"}
            ]
          },
          {
            "id": "fold3",
            "label": "Fold 3",
            "short": "Step 3",
            "sentence": "Fold 3 validation reveals a large divergence in error rates.",
            "why": "Aha: Training error plummets while validation error remains high.",
            "active": ["metricPanel", "valSet"],
            "calloutRegion": "metricPanel",
            "readouts": [
              {"id": "t3", "label": "Train Error", "value": "1.5%"},
              {"id": "v3", "label": "Val Error", "value": "26%"}
            ]
          },
          {
            "id": "fold4",
            "label": "Fold 4",
            "short": "Step 4",
            "sentence": "Fold 4 validation confirms the generalization gap.",
            "why": "Consistent high validation error proves overfitting.",
            "active": ["valSet"],
            "calloutRegion": "valSet",
            "readouts": [
              {"id": "t4", "label": "Train Error", "value": "2%"},
              {"id": "v4", "label": "Val Error", "value": "22%"}
            ]
          },
          {
            "id": "fold5",
            "label": "Fold 5",
            "short": "Step 5",
            "sentence": "Final fold completes the rotation cycle.",
            "why": "Average validation error summarizes true performance.",
            "active": ["metricPanel"],
            "calloutRegion": "metricPanel",
            "readouts": [
              {"id": "t5", "label": "Train Error", "value": "2%"},
              {"id": "v5", "label": "Val Error", "value": "23%"}
            ]
          }
        ]
      }
    ]
  }
}
